	/**
	 * Default Constructor
	 */
    public WorkAuthorizationService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new WorkAuthorizationEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(WorkAuthorizationRepository.class) );
		this.validator		= applicationContext.getBean(WorkAuthorizationValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		WorkAuthorization
	 */
		public WorkAuthorization createWorkAuthorization( CreateWorkAuthorizationCommand command ) {

		WorkAuthorization entity = new WorkAuthorization();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setWorkAuthorizationId( command.getWorkAuthorizationId() );
            entity.setCountry( command.getCountry() );
            entity.setExpirationDate( command.getExpirationDate() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of WorkAuthorization {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateWorkAuthorizationCommand
	 * @return		WorkAuthorization
	 */
	public WorkAuthorization updateWorkAuthorization( UpdateWorkAuthorizationCommand command ) {

		WorkAuthorization entity = new WorkAuthorization();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setWorkAuthorizationId( command.getWorkAuthorizationId() );
            entity.setCountry( command.getCountry() );
            entity.setExpirationDate( command.getExpirationDate() );
            entity.setEmployee( command.getEmployee() );
            entity.setDocuments( command.getDocuments() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of WorkAuthorization {0} ", entity.toString() );

		return entity;
	}

